// ─── App ──────────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const mapElRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<import('leaflet').Map | null>(null);
  const markerMapRef = useRef<Map<string, import('leaflet').Marker>>(new Map());
  const [coords, setCoords] = useState({ lat: 0, lng: 0, zoom: 2 });
  const [ready, setReady] = useState(false);
  const [activePlace, setActivePlace] = useState<string | null>(null);

  const handlePlaceSelect = useCallback((id: string) => {
    const info = PLACE_INFO[id];
    if (info && mapRef.current) {
      mapRef.current.flyTo([info.lat, info.lng], info.zoom, { duration: 1.2 });
      setActivePlace(id);
    }
  }, []);

  function handleNavSelect(entry: NavEntry) {
    handlePlaceSelect(entry.id);
  }

  const handleReset = () => {
    mapRef.current?.flyTo([20, 0], 2, { duration: 1.2 });
    setActivePlace(null);
  };

  const activePlaceInfo = useMemo(
    () => activePlace ? { id: activePlace, ...PLACE_INFO[activePlace] } : null,
    [activePlace],
  );

  // Update active marker CSS class when activePlace changes
  useEffect(() => {
    markerMapRef.current.forEach((marker, id) => {
      const el = marker.getElement()?.querySelector('.flag-marker');
      if (el) {
        el.classList.toggle('active', id === activePlace);
      }
    });
  }, [activePlace]);

  useEffect(() => {
    loadStyle(LEAFLET_CSS);
    loadScript(LEAFLET_JS).then(() => setReady(true));
  }, []);

  useEffect(() => {
    if (!ready || !mapElRef.current || mapRef.current) return;

    const L = window.L;

    const map = L.map(mapElRef.current, {
      center: [20, 0],
      zoom: 2,
      zoomControl: true,
      attributionControl: false,
    });

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
      maxZoom: 19,
    }).addTo(map);

    map.on('mousemove', (e) => {
      setCoords((prev) => ({ ...prev, lat: e.latlng.lat, lng: e.latlng.lng }));
    });

    map.on('zoomend', () => {
      setCoords((prev) => ({ ...prev, zoom: map.getZoom() }));
    });

    // Add flag markers for each place
    Object.entries(PLACE_INFO).forEach(([id, info]) => {
      const icon = L.divIcon({
        html: `<div class="flag-marker">${info.flag}</div>`,
        className: '',
        iconSize: [28, 28],
        iconAnchor: [14, 14],
      });

      const marker = L.marker([info.lat, info.lng], { icon });
      marker.on('click', () => {
        map.flyTo([info.lat, info.lng], info.zoom, { duration: 1.2 });
        setActivePlace(id);
      });
      marker.addTo(map);
      markerMapRef.current.set(id, marker);
    });

    mapRef.current = map;

    return () => {
      markerMapRef.current.clear();
      map.remove();
      mapRef.current = null;
    };
  }, [ready]);

  const resetBtn = (
    <ResetBtn onClick={handleReset} title="Reset to world view">
      <svg width={14} height={14} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10" />
        <line x1="2" y1="12" x2="22" y2="12" />
        <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
      </svg>
      World
    </ResetBtn>
  );

  const sidebar = (
    <NavTree entries={PLACES} activeId={activePlace} onSelect={handleNavSelect} />
  );

  return (
    <Layout
      title="Earth"
      sidebar={sidebar}
      activeId={activePlace}
      topBarRight={<>{resetBtn}{topBarRight}</>}
    >
      <MapContainer>
        <MapArea>
          <MapWrapper>
            <div ref={mapElRef} style={{ height: '100%', width: '100%' }} />
          </MapWrapper>
          <WeatherPanel
            place={activePlaceInfo}
            onClose={() => setActivePlace(null)}
          />
        </MapArea>
        <StatusBar>
          <span>Lat: {coords.lat.toFixed(4)}</span>
          <span>Lng: {coords.lng.toFixed(4)}</span>
          <span>Zoom: {coords.zoom}</span>
          <span style={{ marginLeft: 'auto' }}>
            © OpenStreetMap contributors
          </span>
        </StatusBar>
      </MapContainer>
    </Layout>
  );
}
